AssistantMessageToolRequest(name='create', tool_call_id='tooluse_iUrbG1hNK4PI38V0nJ9SiH', arguments={'file_text': '/* ============================================================
   CSS Custom Properties
   ============================================================ */
:root {
  --color-brand-50:  #f0f4ff;
  --color-brand-100: #dce6ff;
  --color-brand-500: #3d5cff;
  --color-brand-600: #2a46e8;
  --color-brand-700: #1e34c7;

  --color-neutral-0:   #ffffff;
  --color-neutral-50:  #f8f9fa;
  --color-neutral-100: #f0f2f5;
  --color-neutral-200: #e4e7ec;
  --color-neutral-400: #9aa0ac;
  --color-neutral-600: #4b5563;
  --color-neutral-700: #374151;
  --color-neutral-900: #111827;

  --color-accent:       #ff5a3c;
  --color-accent-dark:  #e04428;
  --color-success:      #22c55e;
  --color-deal:         #ff5a3c;

  --radius-sm:  4px;
  --radius-md:  8px;
  --radius-lg:  12px;
  --radius-xl:  20px;
  --radius-full: 9999px;

  --shadow-sm:  0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md:  0 4px 12px rgba(0,0,0,.10);
  --shadow-lg:  0 8px 30px rgba(0,0,0,.12);

  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-display: 'Syne', 'Inter', system-ui, sans-serif;

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;

  --max-w: 1280px;
  --gutter: clamp(16px, 4vw, 48px);
}

/* ============================================================
   Reset & Base
   ============================================================ */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }

body {
  font-family: var(--font-sans);
  background: var(--color-neutral-0);
  color: var(--color-neutral-900);
  line-height: 1.6;
  overflow-x: hidden;
}

img, svg { display: block; max-width: 100%; }

a { color: inherit; text-decoration: none; }

button {
  font: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol { list-style: none; }

/* ============================================================
   Skip Link
   ============================================================ */
.skip-link {
  position: fixed;
  top: -100%;
  left: 16px;
  z-index: 9999;
  padding: 10px 20px;
  background: var(--color-brand-500);
  color: var(--color-neutral-0);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: .875rem;
  transition: top var(--transition-fast);
}
.skip-link:focus {
  top: 16px;
  outline: 3px solid var(--color-neutral-900);
  outline-offset: 2px;
}

/* ============================================================
   Focus Visible
   ============================================================ */
:focus-visible {
  outline: 2px solid var(--color-brand-500);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* ============================================================
   Layout Helpers
   ============================================================ */
.container {
  width: 100%;
  max-width: var(--max-w);
  margin-inline: auto;
  padding-inline: var(--gutter);
}

.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 32px;
}

.section-title {
  font-family: var(--font-display);
  font-size: clamp(1.375rem, 3vw, 1.75rem);
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1.2;
}

.view-all-link {
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-brand-500);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  white-space: nowrap;
  transition: color var(--transition-fast), gap var(--transition-fast);
}
.view-all-link:hover, .view-all-link:focus-visible { color: var(--color-brand-700); gap: 8px; }
.view-all-link svg { flex-shrink: 0; }

/* ============================================================
   Announcement Bar
   ============================================================ */
.announcement-bar {
  background: var(--color-brand-500);
  color: var(--color-neutral-0);
  text-align: center;
  padding: 10px var(--gutter);
  font-size: .8125rem;
  font-weight: 500;
  letter-spacing: .02em;
  position: relative;
}

.announcement-bar__close {
  position: absolute;
  right: 16px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--color-neutral-0);
  opacity: .75;
  padding: 4px;
  border-radius: var(--radius-sm);
  transition: opacity var(--transition-fast);
  line-height: 0;
}
.announcement-bar__close:hover,
.announcement-bar__close:focus-visible { opacity: 1; }

/* ============================================================
   Header / Nav
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 200;
  background: rgba(255,255,255,.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-neutral-200);
  transition: box-shadow var(--transition-base);
}
.site-header.scrolled { box-shadow: var(--shadow-md); }

.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  height: 64px;
}

/* Logo */
.site-logo {
  font-family: var(--font-display);
  font-size: 1.375rem;
  font-weight: 800;
  letter-spacing: -.04em;
  color: var(--color-neutral-900);
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}
.site-logo__mark {
  width: 28px;
  height: 28px;
  background: var(--color-brand-500);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
}

/* Primary Nav */
.primary-nav { display: flex; align-items: center; justify-content: center; gap: 4px; }

.nav-link {
  padding: 6px 14px;
  font-size: .9375rem;
  font-weight: 500;
  color: var(--color-neutral-700);
  border-radius: var(--radius-md);
  transition: color var(--transition-fast), background var(--transition-fast);
  white-space: nowrap;
}
.nav-link:hover,
.nav-link:focus-visible { color: var(--color-neutral-900); background: var(--color-neutral-100); }
.nav-link[aria-current="page"] { color: var(--color-brand-500); font-weight: 600; }

/* Header Actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

.icon-btn {
  position: relative;
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-md);
  color: var(--color-neutral-700);
  transition: color var(--transition-fast), background var(--transition-fast);
}
.icon-btn:hover,
.icon-btn:focus-visible { color: var(--color-neutral-900); background: var(--color-neutral-100); }

.cart-badge {
  position: absolute;
  top: 4px;
  right: 4px;
  min-width: 16px;
  height: 16px;
  padding-inline: 4px;
  background: var(--color-accent);
  color: white;
  font-size: .625rem;
  font-weight: 700;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.menu-btn { display: none; }

/* Search overlay */
.search-overlay {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 300;
  background: rgba(0,0,0,.4);
  align-items: flex-start;
  justify-content: center;
  padding-top: 80px;
}
.search-overlay.open { display: flex; }

.search-box {
  background: var(--color-neutral-0);
  border-radius: var(--radius-lg);
  padding: 20px;
  width: min(600px, calc(100vw - 32px));
  box-shadow: var(--shadow-lg);
}

.search-input-wrap {
  display: flex;
  align-items: center;
  gap: 12px;
  border: 2px solid var(--color-brand-500);
  border-radius: var(--radius-md);
  padding: 8px 16px;
}

.search-input {
  flex: 1;
  border: none;
  outline: none;
  font: inherit;
  font-size: 1rem;
  color: var(--color-neutral-900);
  background: transparent;
}

.search-close {
  margin-top: 12px;
  font-size: .8125rem;
  color: var(--color-neutral-400);
  font-weight: 500;
}
.search-close kbd {
  background: var(--color-neutral-100);
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--color-neutral-200);
  font-size: .75rem;
}

/* ============================================================
   Hero
   ============================================================ */
.hero {
  background: linear-gradient(135deg, #0a0f2e 0%, #1a2560 50%, #0d1a4a 100%);
  color: white;
  padding-block: clamp(48px, 8vw, 96px);
  overflow: hidden;
  position: relative;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 70% 50%, rgba(61,92,255,.25) 0%, transparent 60%);
  pointer-events: none;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(32px, 5vw, 80px);
  align-items: center;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: .8125rem;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: rgba(255,255,255,.65);
  margin-bottom: 20px;
}
.hero-eyebrow span {
  width: 24px;
  height: 2px;
  background: var(--color-brand-500);
  display: inline-block;
}

.hero-title {
  font-family: var(--font-display);
  font-size: clamp(2.25rem, 5vw, 3.75rem);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: -.03em;
  margin-bottom: 24px;
}

.hero-title em {
  font-style: normal;
  color: #7b96ff;
}

.hero-desc {
  font-size: clamp(.9375rem, 2vw, 1.0625rem);
  color: rgba(255,255,255,.72);
  max-width: 44ch;
  line-height: 1.7;
  margin-bottom: 36px;
}

.hero-cta {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-md);
  font-size: .9375rem;
  font-weight: 600;
  line-height: 1;
  transition: background var(--transition-fast), transform var(--transition-fast), box-shadow var(--transition-fast);
  white-space: nowrap;
  cursor: pointer;
  border: 2px solid transparent;
}
.btn:active { transform: translateY(1px); }

.btn-primary {
  background: var(--color-brand-500);
  color: white;
  border-color: var(--color-brand-500);
}
.btn-primary:hover,
.btn-primary:focus-visible { background: var(--color-brand-600); border-color: var(--color-brand-600); box-shadow: 0 4px 14px rgba(61,92,255,.4); }

.btn-outline-white {
  background: transparent;
  color: white;
  border-color: rgba(255,255,255,.35);
}
.btn-outline-white:hover,
.btn-outline-white:focus-visible { background: rgba(255,255,255,.1); border-color: rgba(255,255,255,.6); }

.btn-outline {
  background: transparent;
  color: var(--color-brand-500);
  border-color: var(--color-brand-500);
}
.btn-outline:hover,
.btn-outline:focus-visible { background: var(--color-brand-50); }

.btn-ghost {
  background: transparent;
  color: var(--color-neutral-700);
}
.btn-ghost:hover,
.btn-ghost:focus-visible { background: var(--color-neutral-100); color: var(--color-neutral-900); }

.btn-sm { padding: 8px 16px; font-size: .8125rem; border-radius: var(--radius-sm); }

/* Hero visual */
.hero-visual {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-image-frame {
  width: 100%;
  max-width: 480px;
  aspect-ratio: 4/5;
  border-radius: var(--radius-xl);
  overflow: hidden;
  background: linear-gradient(135deg, #1e2d6e, #2a3d94);
  position: relative;
  box-shadow: 0 32px 80px rgba(0,0,0,.5);
}

.hero-product-mockup {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 40px;
  text-align: center;
}

.hero-product-icon {
  font-size: 5rem;
  filter: drop-shadow(0 8px 24px rgba(0,0,0,.3));
}

.hero-product-label {
  font-size: 1rem;
  color: rgba(255,255,255,.75);
  font-weight: 500;
}

.hero-badge {
  position: absolute;
  top: 24px;
  left: -16px;
  background: white;
  color: var(--color-neutral-900);
  border-radius: var(--radius-lg);
  padding: 12px 16px;
  box-shadow: var(--shadow-lg);
  font-size: .8125rem;
  font-weight: 600;
  min-width: 130px;
}
.hero-badge__label { color: var(--color-neutral-400); font-size: .75rem; font-weight: 400; display: block; margin-bottom: 2px; }
.hero-badge__stars { color: #facc15; font-size: .875rem; display: flex; gap: 1px; align-items: center; }

.hero-badge-2 {
  position: absolute;
  bottom: 40px;
  right: -16px;
  background: var(--color-brand-500);
  color: white;
  border-radius: var(--radius-lg);
  padding: 12px 16px;
  box-shadow: 0 8px 24px rgba(61,92,255,.4);
  font-size: .8125rem;
  font-weight: 600;
}

.hero-stat {
  display: flex;
  gap: 24px;
  margin-top: 36px;
  flex-wrap: wrap;
}
.hero-stat__item { text-align: center; }
.hero-stat__num {
  display: block;
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 800;
  color: white;
  letter-spacing: -.03em;
}
.hero-stat__label {
  font-size: .75rem;
  color: rgba(255,255,255,.55);
  text-transform: uppercase;
  letter-spacing: .05em;
}

/* ============================================================
   Category Strip
   ============================================================ */
.categories-section { padding-block: 40px; }

.categories-scroll {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  padding-bottom: 4px;
  scrollbar-width: none;
}
.categories-scroll::-webkit-scrollbar { display: none; }

.category-card {
  scroll-snap-align: start;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 20px 24px;
  background: var(--color-neutral-50);
  border: 1.5px solid var(--color-neutral-200);
  border-radius: var(--radius-lg);
  cursor: pointer;
  transition: background var(--transition-fast), border-color var(--transition-fast), transform var(--transition-fast);
  min-width: 108px;
  text-align: center;
  font-size: .8125rem;
  font-weight: 600;
  color: var(--color-neutral-700);
}
.category-card:hover,
.category-card:focus-visible {
  background: var(--color-brand-50);
  border-color: var(--color-brand-500);
  color: var(--color-brand-700);
  transform: translateY(-2px);
}
.category-card[aria-pressed="true"] {
  background: var(--color-brand-500);
  border-color: var(--color-brand-500);
  color: white;
}

.category-card__icon { font-size: 1.75rem; line-height: 1; }

/* ============================================================
   Featured Products
   ============================================================ */
.featured-section { padding-block: 56px; }

.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 20px;
}

/* Product Card */
.product-card {
  background: var(--color-neutral-0);
  border: 1.5px solid var(--color-neutral-200);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: box-shadow var(--transition-base), transform var(--transition-base), border-color var(--transition-base);
  display: flex;
  flex-direction: column;
  position: relative;
}
.product-card:hover,
.product-card:focus-within {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
  border-color: var(--color-neutral-300);
}

.product-card__image-wrap {
  position: relative;
  aspect-ratio: 1;
  background: var(--color-neutral-100);
  overflow: hidden;
}

.product-card__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 400ms ease;
}
.product-card:hover .product-card__image { transform: scale(1.04); }

.product-emoji-bg {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4.5rem;
  background: linear-gradient(135deg, var(--color-neutral-50) 0%, var(--color-neutral-100) 100%);
  transition: transform 400ms ease;
}
.product-card:hover .product-emoji-bg { transform: scale(1.08); }

.product-card__badges {
  position: absolute;
  top: 10px;
  left: 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border-radius: var(--radius-full);
  font-size: .6875rem;
  font-weight: 700;
  letter-spacing: .03em;
  text-transform: uppercase;
}
.badge--deal { background: var(--color-accent); color: white; }
.badge--new  { background: var(--color-success); color: white; }
.badge--hot  { background: #f59e0b; color: white; }

.product-card__wishlist {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 34px;
  height: 34px;
  background: white;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
  color: var(--color-neutral-400);
  transition: color var(--transition-fast), transform var(--transition-fast);
  opacity: 0;
}
.product-card:hover .product-card__wishlist,
.product-card:focus-within .product-card__wishlist { opacity: 1; }
.product-card__wishlist:hover,
.product-card__wishlist:focus-visible { color: var(--color-accent); transform: scale(1.1); }
.product-card__wishlist[aria-pressed="true"] { color: var(--color-accent); opacity: 1; }
.product-card__wishlist[aria-pressed="true"] svg { fill: var(--color-accent); }

.product-card__body {
  padding: 16px;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.product-card__category {
  font-size: .6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--color-neutral-400);
}

.product-card__name {
  font-size: .9375rem;
  font-weight: 600;
  color: var(--color-neutral-900);
  line-height: 1.3;
}

.product-card__name a::after {
  content: '';
  position: absolute;
  inset: 0;
}

.product-card__rating {
  display: flex;
  align-items: center;
  gap: 6px;
}
.product-card__stars {
  display: flex;
  gap: 1px;
  color: #facc15;
  font-size: .75rem;
}
.product-card__review-count {
  font-size: .75rem;
  color: var(--color-neutral-400);
}

.product-card__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
  padding-top: 12px;
  gap: 8px;
}

.product-card__price {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.product-card__price-current {
  font-size: 1.0625rem;
  font-weight: 700;
  color: var(--color-neutral-900);
}
.product-card__price-original {
  font-size: .8125rem;
  color: var(--color-neutral-400);
  text-decoration: line-through;
}
.product-card__price-save {
  font-size: .6875rem;
  color: var(--color-accent);
  font-weight: 700;
}

.product-card__add-btn {
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  background: var(--color-brand-500);
  color: white;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition-fast), transform var(--transition-fast);
}
.product-card__add-btn:hover,
.product-card__add-btn:focus-visible { background: var(--color-brand-600); transform: scale(1.05); }
.product-card__add-btn.added {
  background: var(--color-success);
  animation: pop .25s ease;
}

@keyframes pop {
  0%   { transform: scale(1); }
  50%  { transform: scale(1.2); }
  100% { transform: scale(1); }
}

/* ============================================================
   Deals Section
   ============================================================ */
.deals-section {
  padding-block: 56px;
  background: var(--color-neutral-50);
  border-block: 1px solid var(--color-neutral-200);
}

.deals-header-area {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: 32px;
  justify-content: space-between;
}

.deal-timer {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--color-neutral-900);
  color: white;
  padding: 8px 16px;
  border-radius: var(--radius-full);
  font-size: .8125rem;
  font-weight: 600;
}
.deal-timer__label { color: rgba(255,255,255,.6); }
.timer-display {
  display: flex;
  align-items: center;
  gap: 4px;
  font-family: var(--font-display);
  letter-spacing: .04em;
}
.timer-unit {
  background: rgba(255,255,255,.12);
  border-radius: 4px;
  padding: 2px 6px;
  min-width: 30px;
  text-align: center;
  font-size: .875rem;
}
.timer-sep { opacity: .5; }

.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 20px;
}

.deal-card {
  background: var(--color-neutral-0);
  border: 1.5px solid var(--color-neutral-200);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: grid;
  grid-template-columns: 120px 1fr;
  transition: box-shadow var(--transition-base), transform var(--transition-base);
  position: relative;
}
.deal-card:hover,
.deal-card:focus-within {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}

.deal-card__image {
  aspect-ratio: 1;
  background: var(--color-neutral-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
}

.deal-card__body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  justify-content: center;
}

.deal-card__name {
  font-size: .9rem;
  font-weight: 600;
  line-height: 1.3;
  color: var(--color-neutral-900);
}
.deal-card__name a::after {
  content: '';
  position: absolute;
  inset: 0;
}

.deal-card__prices {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
}
.deal-card__price { font-size: 1.0625rem; font-weight: 700; color: var(--color-neutral-900); }
.deal-card__was  { font-size: .8125rem; color: var(--color-neutral-400); text-decoration: line-through; }

.deal-progress {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 4px;
}
.deal-progress__bar {
  height: 6px;
  background: var(--color-neutral-200);
  border-radius: var(--radius-full);
  overflow: hidden;
}
.deal-progress__fill {
  height: 100%;
  background: linear-gradient(90deg, var(--color-accent), #ff8a6e);
  border-radius: var(--radius-full);
  transition: width .6s ease;
}
.deal-progress__text { font-size: .6875rem; color: var(--color-neutral-400); font-weight: 500; }
.deal-progress__text strong { color: var(--color-accent); }

.deal-add-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--color-brand-500);
  color: white;
  padding: 7px 14px;
  border-radius: var(--radius-md);
  font-size: .8125rem;
  font-weight: 600;
  margin-top: 6px;
  width: fit-content;
  transition: background var(--transition-fast);
}
.deal-add-btn:hover,
.deal-add-btn:focus-visible { background: var(--color-brand-600); }

/* ============================================================
   Editorial / Lookbook
   ============================================================ */
.editorial-section { padding-block: 56px; }

.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 20px;
}

.editorial-card {
  position: relative;
  border-radius: var(--radius-xl);
  overflow: hidden;
  background: var(--color-neutral-900);
  min-height: 260px;
  display: flex;
  align-items: flex-end;
  transition: transform var(--transition-base);
}
.editorial-card:hover,
.editorial-card:focus-within { transform: scale(1.01); }

.editorial-card--featured {
  grid-row: 1 / 3;
  min-height: 540px;
}

.editorial-card__bg {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 8rem;
  opacity: .2;
  transition: transform 600ms ease, opacity 300ms ease;
  pointer-events: none;
}
.editorial-card:hover .editorial-card__bg { transform: scale(1.06); opacity: .28; }

.editorial-card__gradient {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.85) 0%, rgba(0,0,0,.2) 50%, transparent 100%);
}

.editorial-card__content {
  position: relative;
  z-index: 1;
  padding: 28px;
  color: white;
  width: 100%;
}

.editorial-card__tag {
  display: inline-block;
  padding: 3px 10px;
  border-radius: var(--radius-full);
  font-size: .6875rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  background: var(--color-brand-500);
  margin-bottom: 10px;
}

.editorial-card__title {
  font-family: var(--font-display);
  font-size: clamp(1.125rem, 2.5vw, 1.5rem);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -.02em;
  margin-bottom: 8px;
}
.editorial-card--featured .editorial-card__title {
  font-size: clamp(1.5rem, 3.5vw, 2rem);
}

.editorial-card__desc { font-size: .875rem; color: rgba(255,255,255,.75); line-height: 1.6; margin-bottom: 16px; }

.editorial-card__link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: .875rem;
  font-weight: 600;
  color: white;
  border-bottom: 1.5px solid rgba(255,255,255,.4);
  padding-bottom: 2px;
  transition: border-color var(--transition-fast), gap var(--transition-fast);
}
.editorial-card__link::after {
  content: '';
  position: absolute;
  inset: 0;
}
.editorial-card:hover .editorial-card__link,
.editorial-card:focus-within .editorial-card__link { border-color: white; gap: 10px; }

/* Color themes for editorial cards */
.editorial-card--teal   { background: linear-gradient(135deg, #0d3d3e, #1a6b6d); }
.editorial-card--indigo { background: linear-gradient(135deg, #1e2060, #3d3f9e); }
.editorial-card--amber  { background: linear-gradient(135deg, #3d2000, #a05c00); }
.editorial-card--rose   { background: linear-gradient(135deg, #3d0020, #8b0044); }

/* ============================================================
   Brands / Trust Strip
   ============================================================ */
.brands-section {
  padding-block: 40px;
  border-block: 1px solid var(--color-neutral-200);
  background: var(--color-neutral-50);
}

.brands-label {
  text-align: center;
  font-size: .8125rem;
  font-weight: 600;
  color: var(--color-neutral-400);
  text-transform: uppercase;
  letter-spacing: .08em;
  margin-bottom: 24px;
}

.brands-scroll {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(24px, 4vw, 56px);
  flex-wrap: wrap;
}

.brand-logo {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(.875rem, 2vw, 1.125rem);
  letter-spacing: -.03em;
  color: var(--color-neutral-300);
  transition: color var(--transition-fast);
  white-space: nowrap;
}
.brand-logo:hover { color: var(--color-neutral-500); }

/* ============================================================
   Newsletter
   ============================================================ */
.newsletter-section {
  padding-block: 64px;
  background: linear-gradient(135deg, #0a0f2e 0%, #1a2560 100%);
  color: white;
}

.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.newsletter-title {
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 3.5vw, 2.25rem);
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1.1;
  margin-bottom: 12px;
}
.newsletter-title span { color: #7b96ff; }

.newsletter-desc {
  font-size: .9375rem;
  color: rgba(255,255,255,.65);
  max-width: 44ch;
}

.newsletter-form { display: flex; flex-direction: column; gap: 12px; }

.newsletter-email-row {
  display: flex;
  gap: 0;
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1.5px solid rgba(255,255,255,.2);
  transition: border-color var(--transition-fast);
  background: rgba(255,255,255,.07);
}
.newsletter-email-row:focus-within { border-color: rgba(255,255,255,.6); }

.newsletter-email {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  padding: 13px 16px;
  font: inherit;
  font-size: .9375rem;
  color: white;
  min-width: 0;
}
.newsletter-email::placeholder { color: rgba(255,255,255,.35); }

.newsletter-submit {
  background: var(--color-brand-500);
  color: white;
  padding: 13px 20px;
  font: inherit;
  font-size: .9375rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: background var(--transition-fast);
  white-space: nowrap;
  flex-shrink: 0;
}
.newsletter-submit:hover,
.newsletter-submit:focus-visible { background: var(--color-brand-600); }
.newsletter-submit:focus-visible { outline: 2px solid white; outline-offset: -2px; }

.newsletter-consent {
  font-size: .75rem;
  color: rgba(255,255,255,.45);
}

.newsletter-success {
  display: none;
  align-items: center;
  gap: 10px;
  color: var(--color-success);
  font-weight: 600;
  font-size: .9375rem;
  padding: 14px 0;
}
.newsletter-success.visible { display: flex; }

/* ============================================================
   Footer
   ============================================================ */
.site-footer {
  background: var(--color-neutral-900);
  color: rgba(255,255,255,.65);
  padding-block: 56px 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: clamp(24px, 4vw, 56px);
  margin-bottom: 48px;
}

.footer-brand .site-logo { color: white; margin-bottom: 16px; }
.footer-brand p { font-size: .875rem; line-height: 1.7; max-width: 32ch; }

.footer-social {
  display: flex;
  gap: 8px;
  margin-top: 20px;
}

.footer-social-link {
  width: 36px;
  height: 36px;
  background: rgba(255,255,255,.08);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,.65);
  transition: background var(--transition-fast), color var(--transition-fast);
  font-size: .75rem;
  font-weight: 700;
}
.footer-social-link:hover,
.footer-social-link:focus-visible { background: var(--color-brand-500); color: white; }

.footer-col h3 {
  font-size: .875rem;
  font-weight: 700;
  color: white;
  text-transform: uppercase;
  letter-spacing: .06em;
  margin-bottom: 16px;
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.footer-links a {
  font-size: .875rem;
  transition: color var(--transition-fast);
}
.footer-links a:hover,
.footer-links a:focus-visible { color: white; }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.1);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  font-size: .8125rem;
}

.footer-legal { display: flex; gap: 16px; flex-wrap: wrap; }
.footer-legal a { transition: color var(--transition-fast); }
.footer-legal a:hover,
.footer-legal a:focus-visible { color: white; }

/* ============================================================
   Cart Drawer
   ============================================================ */
.cart-overlay {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 400;
  background: rgba(0,0,0,.4);
}
.cart-overlay.open { display: block; }

.cart-drawer {
  position: fixed;
  top: 0;
  right: 0;
  height: 100dvh;
  width: min(400px, 100vw);
  background: white;
  z-index: 401;
  display: flex;
  flex-direction: column;
  transform: translateX(100%);
  transition: transform var(--transition-base);
  box-shadow: -8px 0 40px rgba(0,0,0,.15);
}
.cart-drawer.open { transform: translateX(0); }

.cart-drawer__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  border-bottom: 1px solid var(--color-neutral-200);
}
.cart-drawer__title {
  font-family: var(--font-display);
  font-size: 1.125rem;
  font-weight: 700;
}
.cart-drawer__count {
  background: var(--color-brand-500);
  color: white;
  border-radius: var(--radius-full);
  min-width: 22px;
  height: 22px;
  font-size: .75rem;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding-inline: 6px;
}

.cart-drawer__body { flex: 1; overflow-y: auto; padding: 24px; }

.cart-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  gap: 12px;
  color: var(--color-neutral-400);
  text-align: center;
}
.cart-empty__icon { font-size: 3.5rem; }
.cart-empty p { font-size: .9375rem; max-width: 24ch; }

.cart-items { display: flex; flex-direction: column; gap: 16px; }

.cart-item {
  display: grid;
  grid-template-columns: 64px 1fr auto;
  gap: 12px;
  align-items: center;
  padding: 12px;
  background: var(--color-neutral-50);
  border-radius: var(--radius-md);
}

.cart-item__img {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-md);
  background: var(--color-neutral-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
}

.cart-item__name { font-size: .875rem; font-weight: 600; color: var(--color-neutral-900); margin-bottom: 4px; }
.cart-item__price { font-size: .875rem; font-weight: 700; color: var(--color-neutral-900); }

.cart-item__qty {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 4px;
}
.qty-btn {
  width: 22px; height: 22px;
  border-radius: 4px;
  background: var(--color-neutral-200);
  color: var(--color-neutral-700);
  font-size: .875rem;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition-fast);
}
.qty-btn:hover { background: var(--color-neutral-300); }
.qty-val { font-size: .8125rem; font-weight: 600; min-width: 16px; text-align: center; }

.cart-item__remove {
  color: var(--color-neutral-400);
  width: 28px; height: 28px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-sm);
  transition: color var(--transition-fast), background var(--transition-fast);
}
.cart-item__remove:hover,
.cart-item__remove:focus-visible { color: var(--color-accent); background: #fff0ee; }

.cart-drawer__footer {
  border-top: 1px solid var(--color-neutral-200);
  padding: 24px;
}

.cart-totals { margin-bottom: 16px; }
.cart-totals__row {
  display: flex;
  justify-content: space-between;
  font-size: .875rem;
  padding-block: 4px;
  color: var(--color-neutral-700);
}
.cart-totals__row--total {
  font-weight: 700;
  font-size: 1rem;
  color: var(--color-neutral-900);
  border-top: 1px solid var(--color-neutral-200);
  padding-top: 10px;
  margin-top: 6px;
}

.checkout-btn {
  width: 100%;
  padding: 14px;
  background: var(--color-neutral-900);
  color: white;
  border-radius: var(--radius-md);
  font: inherit;
  font-size: .9375rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: background var(--transition-fast);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.checkout-btn:hover,
.checkout-btn:focus-visible { background: var(--color-brand-700); }
.checkout-btn:focus-visible { outline: 2px solid var(--color-brand-500); outline-offset: 2px; }

/* ============================================================
   Toast Notification
   ============================================================ */
#toast-region {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 500;
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: center;
  pointer-events: none;
}

.toast {
  background: var(--color-neutral-900);
  color: white;
  padding: 12px 20px;
  border-radius: var(--radius-full);
  font-size: .875rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 8px;
  box-shadow: var(--shadow-lg);
  animation: toast-in .25s ease, toast-out .3s ease 2.5s forwards;
  pointer-events: auto;
  white-space: nowrap;
}
.toast__icon { font-size: 1rem; }

@keyframes toast-in {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes toast-out {
  from { opacity: 1; transform: translateY(0); }
  to   { opacity: 0; transform: translateY(8px); }
}

/* ============================================================
   Responsive
   ============================================================ */
@media (max-width: 1024px) {
  .hero-grid {
    grid-template-columns: 1fr;
    text-align: center;
  }
  .hero-eyebrow { justify-content: center; }
  .hero-desc { margin-inline: auto; }
  .hero-cta { justify-content: center; }
  .hero-stat { justify-content: center; }
  .hero-visual { display: none; }

  .editorial-card--featured { grid-column: 1 / -1; min-height: 320px; }
  .editorial-grid { grid-template-columns: 1fr 1fr; grid-template-rows: auto; }

  .newsletter-inner { grid-template-columns: 1fr; gap: 28px; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .primary-nav { display: none; }
  .menu-btn { display: flex; }

  .header-inner { grid-template-columns: auto 1fr auto; }

  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card--featured { min-height: 280px; }

  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }

  .cart-drawer { width: 100vw; }
}

@media (max-width: 540px) {
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
  .hero-stat { gap: 16px; }
  .deal-card { grid-template-columns: 100px 1fr; }
}

/* ============================================================
   Mobile Nav Drawer
   ============================================================ */
.mobile-nav-overlay {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 300;
  background: rgba(0,0,0,.45);
}
.mobile-nav-overlay.open { display: block; }

.mobile-nav-drawer {
  position: fixed;
  top: 0;
  left: 0;
  height: 100dvh;
  width: min(300px, 85vw);
  background: white;
  z-index: 301;
  transform: translateX(-100%);
  transition: transform var(--transition-base);
  display: flex;
  flex-direction: column;
}
.mobile-nav-drawer.open { transform: translateX(0); }

.mobile-nav-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  border-bottom: 1px solid var(--color-neutral-200);
}

.mobile-nav-links {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  overflow-y: auto;
  flex: 1;
}

.mobile-nav-link {
  padding: 12px 16px;
  border-radius: var(--radius-md);
  font-size: .9375rem;
  font-weight: 500;
  color: var(--color-neutral-700);
  transition: background var(--transition-fast), color var(--transition-fast);
  display: block;
}
.mobile-nav-link:hover,
.mobile-nav-link:focus-visible { background: var(--color-neutral-100); color: var(--color-neutral-900); }

/* ============================================================
   Reduced Motion
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .01ms !important;
    transition-duration: .01ms !important;
  }
  html { scroll-behavior: auto; }
}

/* ============================================================
   Forced Colors
   ============================================================ */
@media (forced-colors: active) {
  .btn-primary,
  .product-card__add-btn,
  .deal-add-btn,
  .newsletter-submit,
  .checkout-btn {
    border: 2px solid ButtonText;
    forced-color-adjust: none;
    background: ButtonFace;
    color: ButtonText;
  }
  .badge--deal,
  .badge--new,
  .badge--hot,
  .cart-badge { background: Highlight; color: HighlightText; }
  .site-header { border-bottom-color: ButtonBorder; }
}
