    title: 'Summer Essentials: The Edit',
    desc: 'Sun, sea, and seriously good style. Discover this season\'s most-loved pieces curated by our in-house creative team.',
    emoji: '☀️', colorClass: 'editorial-card--teal',
    href: '#editorial',
  },
  {
    id: 'e2', tag: 'Guide',
    title: 'Tech Picks for Remote Workers',
    desc: 'Power up your home office with tools that actually make a difference.',
    emoji: '💻', colorClass: 'editorial-card--indigo',
    href: '#editorial',
  },
  {
    id: 'e3', tag: 'Trend',
    title: 'Outdoor Adventure Gear 2026',
    desc: 'Trail-ready favourites for every kind of explorer.',
    emoji: '⛰️', colorClass: 'editorial-card--amber',
    href: '#editorial',
  },
];

/* ── State ──────────────────────────────────────────────────── */

const state = {
  cart: [],
  wishlist: new Set(),
  cartOpen: false,
  mobileNavOpen: false,
  searchOpen: false,
  timerEnd: Date.now() + 2 * 60 * 60 * 1000 + 47 * 60 * 1000 + 12 * 1000,
};

/* ── Helpers ────────────────────────────────────────────────── */

const $ = (sel, ctx = document) => ctx.querySelector(sel);
const $$ = (sel, ctx = document) => [...ctx.querySelectorAll(sel)];
const fmt = (n) => '$' + Number(n).toFixed(2);
const stars = (r) => {
  const full  = Math.floor(r);
  const half  = r % 1 >= .5 ? 1 : 0;
  const empty = 5 - full - half;
  return '★'.repeat(full) + (half ? '½' : '') + '☆'.repeat(empty);
};
const pct = (price, was) => Math.round((1 - price / was) * 100);

function trapFocus(el) {
  const focusable = () => $$('a,button,input,textarea,select,[tabindex]:not([tabindex="-1"])', el)
    .filter(e => !e.disabled && !e.closest('[hidden]') && e.offsetParent !== null);
  function handler(e) {
    if (e.key !== 'Tab') return;
    const items = focusable();
    if (!items.length) { e.preventDefault(); return; }
    const first = items[0], last = items[items.length - 1];
    if (e.shiftKey ? document.activeElement === first : document.activeElement === last) {
      e.preventDefault();
      (e.shiftKey ? last : first).focus();
    }
  }
  el.addEventListener('keydown', handler);
  return () => el.removeEventListener('keydown', handler);
}

/* ── Rendering helpers ──────────────────────────────────────── */

function renderStars(rating) {
  return Array.from({ length: 5 }, (_, i) => {
    const full = i < Math.floor(rating);
    const half = !full && i < rating;
    return `<span aria-hidden="true" style="color:${full || half ? '#facc15' : '#d1d5db'}">${full ? '★' : half ? '⯨' : '☆'}</span>`;
  }).join('');
}

function renderBadge(badge) {
  if (!badge) return '';
  const map = { deal: ['deal', 'Sale'], new: ['new', 'New'], hot: ['hot', '🔥 Hot'] };
  const [cls, label] = map[badge] || [];
  return `<span class="badge badge--${cls}">${label}</span>`;
}

function productCardHTML(p) {
  const savePct = p.originalPrice ? pct(p.price, p.originalPrice) : 0;
  return /* html */`
    <article class="product-card" data-product-id="${p.id}">
      <div class="product-card__image-wrap">
        <div class="product-emoji-bg" aria-hidden="true">${p.emoji}</div>
        <div class="product-card__badges">${renderBadge(p.badge)}</div>
        <button
          class="product-card__wishlist"
          aria-label="Save ${p.name} to wishlist"
          aria-pressed="false"
          data-wishlist-id="${p.id}"
        >
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">
            <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/>
          </svg>
        </button>
      </div>
      <div class="product-card__body">
        <p class="product-card__category">${p.category}</p>
        <h3 class="product-card__name">
          <a href="#product-${p.id}">${p.name}</a>
        </h3>
        <div class="product-card__rating">
          <span class="product-card__stars" aria-hidden="true">${renderStars(p.rating)}</span>
          <span class="product-card__review-count" aria-label="${p.rating} out of 5, ${p.reviews.toLocaleString()} reviews">
            ${p.rating} (${p.reviews.toLocaleString()})
          </span>
        </div>
        <div class="product-card__footer">
          <div class="product-card__price">
            <span class="product-card__price-current">${fmt(p.price)}</span>
            ${p.originalPrice ? `
              <span class="product-card__price-original" aria-label="Was ${fmt(p.originalPrice)}">${fmt(p.originalPrice)}</span>
              <span class="product-card__price-save" aria-label="Save ${savePct}%">Save ${savePct}%</span>
            ` : ''}
          </div>
          <button
            class="product-card__add-btn"
            aria-label="Add ${p.name} to cart"
            data-add-id="${p.id}"
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true">
              <line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/>
            </svg>
          </button>
        </div>
      </div>
    </article>`;
}

function dealCardHTML(d) {
  const pctOff = pct(d.price, d.was);
  const remaining = 100 - d.sold;
  return /* html */`
    <article class="deal-card" data-deal-id="${d.id}">
      <div class="deal-card__image" aria-hidden="true">${d.emoji}</div>
      <div class="deal-card__body">
        <p class="deal-card__name">
          <a href="#deal-${d.id}">${d.name}</a>
        </p>
        <div class="deal-card__prices">
          <span class="deal-card__price">${fmt(d.price)}</span>
          <span class="deal-card__was" aria-label="Was ${fmt(d.was)}">${fmt(d.was)}</span>
          <span class="badge badge--deal" aria-label="${pctOff}% off">–${pctOff}%</span>
        </div>
        <div class="deal-progress" role="presentation">
          <div class="deal-progress__bar">
            <div
              class="deal-progress__fill"
              role="progressbar"
              aria-valuenow="${d.sold}"
              aria-valuemin="0"
              aria-valuemax="100"
              aria-label="${d.sold}% claimed"
              style="width:${d.sold}%"
            ></div>
          </div>
          <p class="deal-progress__text">
            <strong>${remaining}%</strong> remaining — selling fast!
          </p>
        </div>
        <button class="deal-add-btn" data-deal-add-id="${d.id}" aria-label="Add ${d.name} to cart">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true">
            <line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/>
          </svg>
          Add to cart
        </button>
      </div>
    </article>`;
}

function editorialCardHTML(e) {
  return /* html */`
    <article class="editorial-card ${e.colorClass}${e.featured ? ' editorial-card--featured' : ''}">
      <div class="editorial-card__bg" aria-hidden="true">${e.emoji}</div>
      <div class="editorial-card__gradient" aria-hidden="true"></div>
      <div class="editorial-card__content">
        <span class="editorial-card__tag">${e.tag}</span>
        <h3 class="editorial-card__title">${e.title}</h3>
        <p class="editorial-card__desc">${e.desc}</p>
        <a class="editorial-card__link" href="${e.href}">
          Read the story
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true">
            <polyline points="9 18 15 12 9 6"/>
          </svg>
        </a>
      </div>
    </article>`;
}

/* ── Cart ───────────────────────────────────────────────────── */

function cartTotal() {
  return state.cart.reduce((sum, item) => sum + item.price * item.qty, 0);
}

function cartItemCount() {
  return state.cart.reduce((sum, item) => sum + item.qty, 0);
}

function updateCartBadge() {
  const count = cartItemCount();
  const badge = $('#cart-badge');
  if (badge) {
    badge.textContent = count;
    badge.hidden = count === 0;
  }
  const drawerCount = $('#cart-drawer-count');
  if (drawerCount) drawerCount.textContent = count;
}

function renderCartItems() {
  const body = $('#cart-drawer-body');
  if (!body) return;

  if (state.cart.length === 0) {
    body.innerHTML = `
      <div class="cart-empty">
        <span class="cart-empty__icon" aria-hidden="true">🛒</span>
        <p>Your cart is empty.<br>Start shopping to add items.</p>
      </div>`;
    return;
  }

  const totals = state.cart.reduce(
    (acc, it) => ({ sub: acc.sub + it.price * it.qty }),
    { sub: 0 }
  );
  const shipping = totals.sub > 75 ? 0 : 5.99;
  const total = totals.sub + shipping;

  body.innerHTML = `
    <ul class="cart-items" aria-label="Cart items">
      ${state.cart.map(item => `
        <li class="cart-item">
          <div class="cart-item__img" aria-hidden="true">${item.emoji}</div>
          <div>
            <p class="cart-item__name">${item.name}</p>
            <p class="cart-item__price">${fmt(item.price)}</p>
            <div class="cart-item__qty" role="group" aria-label="Quantity for ${item.name}">
              <button class="qty-btn" data-qty-dec="${item.id}" aria-label="Decrease quantity">−</button>
              <span class="qty-val" aria-live="polite" aria-atomic="true">${item.qty}</span>
              <button class="qty-btn" data-qty-inc="${item.id}" aria-label="Increase quantity">+</button>
            </div>
          </div>
          <button class="cart-item__remove" data-remove-id="${item.id}" aria-label="Remove ${item.name} from cart">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">
              <polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14H6L5 6"/><path d="M10 11v6m4-6v6"/><path d="M9 6V4h6v2"/>
            </svg>
          </button>
        </li>
      `).join('')}
    </ul>
    <div class="cart-totals" style="margin-top:20px">
      <div class="cart-totals__row"><span>Subtotal</span><span>${fmt(totals.sub)}</span></div>
      <div class="cart-totals__row"><span>Shipping</span><span>${shipping === 0 ? '<strong style="color:var(--color-success)">Free</strong>' : fmt(shipping)}</span></div>
      <div class="cart-totals__row cart-totals__row--total"><span>Total</span><span>${fmt(total)}</span></div>
    </div>`;
}

function addToCart(productId) {
  const product = [...PRODUCTS, ...DEALS.map(d => ({
    id: d.id, name: d.name, emoji: d.emoji, price: d.price,
  }))].find(p => p.id === productId);
  if (!product) return;

  const existing = state.cart.find(i => i.id === productId);
  if (existing) {
    existing.qty += 1;
  } else {
    state.cart.push({ ...product, qty: 1 });
  }
  updateCartBadge();
  renderCartItems();
  showToast(`${product.emoji} ${product.name} added to cart`);
}

function removeFromCart(productId) {
  state.cart = state.cart.filter(i => i.id !== productId);
  updateCartBadge();
  renderCartItems();
}

function changeQty(productId, delta) {
  const item = state.cart.find(i => i.id === productId);
  if (!item) return;
  item.qty = Math.max(1, item.qty + delta);
  updateCartBadge();
  renderCartItems();
}

/* ── Cart Drawer open/close ─────────────────────────────────── */

let cartTrapCleanup = null;
let lastCartTrigger = null;

function openCart(trigger) {
  lastCartTrigger = trigger || null;
  state.cartOpen = true;
  const overlay = $('#cart-overlay');
  const drawer = $('#cart-drawer');
  overlay.classList.add('open');
  drawer.classList.add('open');
  drawer.removeAttribute('hidden');
  overlay.removeAttribute('hidden');
  renderCartItems();
  const closeBtn = $('#cart-close-btn');
  if (closeBtn) closeBtn.focus();
  cartTrapCleanup = trapFocus(drawer);
  document.body.style.overflow = 'hidden';
}

function closeCart() {
  state.cartOpen = false;
  const overlay = $('#cart-overlay');
  const drawer = $('#cart-drawer');
  overlay.classList.remove('open');
  drawer.classList.remove('open');
  if (cartTrapCleanup) { cartTrapCleanup(); cartTrapCleanup = null; }
  document.body.style.overflow = '';
  if (lastCartTrigger) { lastCartTrigger.focus(); lastCartTrigger = null; }
}

/* ── Mobile Nav ─────────────────────────────────────────────── */

let navTrapCleanup = null;
let lastNavTrigger = null;

function openMobileNav(trigger) {
  lastNavTrigger = trigger || null;
  state.mobileNavOpen = true;
  $('#mobile-nav-overlay').classList.add('open');
  $('#mobile-nav-drawer').classList.add('open');
  $('#mobile-nav-close').focus();
  navTrapCleanup = trapFocus($('#mobile-nav-drawer'));
  document.body.style.overflow = 'hidden';
}

function closeMobileNav() {
  state.mobileNavOpen = false;
  $('#mobile-nav-overlay').classList.remove('open');
  $('#mobile-nav-drawer').classList.remove('open');
  if (navTrapCleanup) { navTrapCleanup(); navTrapCleanup = null; }
  document.body.style.overflow = '';
  if (lastNavTrigger) { lastNavTrigger.focus(); lastNavTrigger = null; }
}

/* ── Search ─────────────────────────────────────────────────── */

let searchTrapCleanup = null;
let lastSearchTrigger = null;

function openSearch(trigger) {
  lastSearchTrigger = trigger || null;
  state.searchOpen = true;
  const overlay = $('#search-overlay');
  overlay.classList.add('open');
  overlay.removeAttribute('hidden');
  const input = $('#search-input');
  if (input) setTimeout(() => input.focus(), 50);
  searchTrapCleanup = trapFocus(overlay);
  document.body.style.overflow = 'hidden';
}

function closeSearch() {
  state.searchOpen = false;
  const overlay = $('#search-overlay');
  overlay.classList.remove('open');
  if (searchTrapCleanup) { searchTrapCleanup(); searchTrapCleanup = null; }
  document.body.style.overflow = '';
  if (lastSearchTrigger) { lastSearchTrigger.focus(); lastSearchTrigger = null; }
}

/* ── Toast ──────────────────────────────────────────────────── */

function showToast(msg) {
  const region = $('#toast-region');
  const toast = document.createElement('div');
  toast.className = 'toast';
  toast.setAttribute('role', 'status');
  toast.setAttribute('aria-live', 'polite');
  toast.setAttribute('aria-atomic', 'true');
  toast.innerHTML = `<span class="toast__icon" aria-hidden="true">✓</span> ${msg}`;
  region.appendChild(toast);
  setTimeout(() => toast.remove(), 2900);
}

/* ── Countdown Timer ────────────────────────────────────────── */

function updateTimer() {
  const remaining = Math.max(0, state.timerEnd - Date.now());
  const h = Math.floor(remaining / 3600000);
  const m = Math.floor((remaining % 3600000) / 60000);
  const s = Math.floor((remaining % 60000) / 1000);
  const pad = n => String(n).padStart(2, '0');

  const hEl = $('#timer-h'), mEl = $('#timer-m'), sEl = $('#timer-s');
  if (hEl) hEl.textContent = pad(h);
  if (mEl) mEl.textContent = pad(m);
  if (sEl) sEl.textContent = pad(s);

  const live = $('#timer-live');
  if (live) live.textContent = `Flash sale ends in ${pad(h)} hours ${pad(m)} minutes ${pad(s)} seconds`;
}

/* ── Scroll behaviours ──────────────────────────────────────── */

function initScrollBehaviours() {
  const header = $('.site-header');
  const onScroll = () => {
    header.classList.toggle('scrolled', window.scrollY > 8);
  };
  window.addEventListener('scroll', onScroll, { passive: true });
  onScroll();
}

/* ── Announcement bar close ─────────────────────────────────── */

function initAnnouncementBar() {
  const bar = $('#announcement-bar');
  const closeBtn = $('#announcement-close');
  if (!bar || !closeBtn) return;

  closeBtn.addEventListener('click', () => {
    bar.hidden = true;
    document.documentElement.style.setProperty('--announcement-height', '0px');
  });
}

/* ── Wishlist ───────────────────────────────────────────────── */

function toggleWishlist(productId, btn) {
  const isIn = state.wishlist.has(productId);
  if (isIn) {
    state.wishlist.delete(productId);
    btn.setAttribute('aria-pressed', 'false');
    btn.setAttribute('aria-label', `Save ${getProductName(productId)} to wishlist`);
  } else {
    state.wishlist.add(productId);
    btn.setAttribute('aria-pressed', 'true');
    btn.setAttribute('aria-label', `Remove ${getProductName(productId)} from wishlist`);
    showToast(`❤️ Saved to wishlist`);
  }
}

function getProductName(id) {
  return [...PRODUCTS, ...DEALS.map(d => ({ id: d.id, name: d.name }))]
    .find(p => p.id === id)?.name ?? 'item';
}

/* ── Newsletter ─────────────────────────────────────────────── */

function initNewsletter() {
  const form = $('#newsletter-form');
  if (!form) return;
  form.addEventListener('submit', e => {
    e.preventDefault();
    const email = $('#newsletter-email');
    if (!email.value.trim()) {
      email.setAttribute('aria-invalid', 'true');
      email.focus();
      return;
    }
    email.removeAttribute('aria-invalid');
    form.hidden = true;
    const success = $('#newsletter-success');
    if (success) {
      success.classList.add('visible');
      success.focus();
    }
  });
}

/* ── Category filter ────────────────────────────────────────── */

function initCategoryFilter() {
  const btns = $$('[data-category-btn]');
  const grid = $('#products-grid');
  if (!grid || !btns.length) return;

  btns.forEach(btn => {
    btn.addEventListener('click', () => {
      const cat = btn.dataset.categoryBtn;

      btns.forEach(b => {
        b.setAttribute('aria-pressed', 'false');
      });
      btn.setAttribute('aria-pressed', 'true');

      const filtered = cat === 'All'
        ? PRODUCTS
        : PRODUCTS.filter(p => p.category === cat);

      grid.innerHTML = filtered.map(productCardHTML).join('');
    });
  });
}

/* ── Event delegation ───────────────────────────────────────── */

function initEventDelegation() {
  document.addEventListener('click', e => {
    const t = e.target;

    // Add to cart — products
    const addBtn = t.closest('[data-add-id]');
    if (addBtn) {
      addToCart(addBtn.dataset.addId);
      addBtn.classList.add('added');
      setTimeout(() => addBtn.classList.remove('added'), 800);
      return;
    }

    // Add to cart — deals
    const dealAddBtn = t.closest('[data-deal-add-id]');
    if (dealAddBtn) {
      addToCart(dealAddBtn.dataset.dealAddId);
      return;
    }

    // Wishlist
    const wishBtn = t.closest('[data-wishlist-id]');
    if (wishBtn) {
      e.preventDefault();
      toggleWishlist(wishBtn.dataset.wishlistId, wishBtn);
      return;
    }

    // Cart qty
    const incBtn = t.closest('[data-qty-inc]');
    if (incBtn) { changeQty(incBtn.dataset.qtyInc, 1); return; }
    const decBtn = t.closest('[data-qty-dec]');
    if (decBtn) { changeQty(decBtn.dataset.qtyDec, -1); return; }

    // Remove from cart
    const removeBtn = t.closest('[data-remove-id]');
    if (removeBtn) { removeFromCart(removeBtn.dataset.removeId); return; }

    // Cart open
    if (t.closest('#cart-open-btn')) {
      openCart(t.closest('#cart-open-btn'));
      return;
    }

    // Cart close
    if (t.closest('#cart-close-btn') || (t.id === 'cart-overlay')) {
      closeCart();
      return;
    }

    // Mobile nav open
    if (t.closest('#menu-btn')) {
      openMobileNav(t.closest('#menu-btn'));
      return;
    }

    // Mobile nav close
    if (t.closest('#mobile-nav-close') || (t.id === 'mobile-nav-overlay')) {
      closeMobileNav();
      return;
    }

    // Search open
    if (t.closest('#search-open-btn')) {
      openSearch(t.closest('#search-open-btn'));
      return;
    }

    // Search close
    if (t.closest('#search-close-btn') || (t.id === 'search-overlay')) {
      closeSearch();
      return;
    }
  });

  // Keyboard escape
  document.addEventListener('keydown', e => {
    if (e.key !== 'Escape') return;
    if (state.cartOpen)      { closeCart(); return; }
    if (state.mobileNavOpen) { closeMobileNav(); return; }
    if (state.searchOpen)    { closeSearch(); return; }
  });
}

/* ── Mount dynamic sections ─────────────────────────────────── */

function mountSections() {
  const productsGrid = $('#products-grid');
  if (productsGrid) productsGrid.innerHTML = PRODUCTS.map(productCardHTML).join('');

  const dealsGrid = $('#deals-grid');
  if (dealsGrid) dealsGrid.innerHTML = DEALS.map(dealCardHTML).join('');

  const editorialGrid = $('#editorial-grid');
  if (editorialGrid) editorialGrid.innerHTML = EDITORIAL.map(editorialCardHTML).join('');
}

/* ── Bootstrap ──────────────────────────────────────────────── */

document.addEventListener('DOMContentLoaded', () => {
  mountSections();
  initEventDelegation();
  initScrollBehaviours();
  initAnnouncementBar();
  initNewsletter();
  initCategoryFilter();

  updateTimer();
  setInterval(updateTimer, 1000);

  updateCartBadge();
});
